import { describe, expect, it } from 'vitest'
import vectors from './parity_vectors.json'
import { priority, weightedGeometricScore } from './ranking'

// Vectors are generated by the Python Scientific Core (ignis-pipeline build); the browser mirror
// must reproduce them exactly so interactive re-weighting never changes the science.
describe('TypeScript mirror of the Python Core', () => {
  it('weighted geometric score matches Python for every vector', () => {
    expect(vectors.scores.length).toBeGreaterThan(50)
    for (const v of vectors.scores) {
      expect(weightedGeometricScore(v.factors, v.weights)).toBeCloseTo(v.expected, 6)
    }
  })
  it('gap priority matches Python for every vector', () => {
    expect(vectors.priorities.length).toBeGreaterThan(10)
    for (const v of vectors.priorities) {
      expect(priority(v.cell, v.scenarios)).toBeCloseTo(v.expected, 6)
    }
  })
})
